<script setup lang="ts">
import {computed,inject,nextTick,onBeforeUnmount,ref,watch,type ComputedRef} from 'vue';
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRouter} from 'vue-router';
import {ArrowDown,ArrowUp,CheckCircle2,Columns3,GitBranch,GripVertical,LoaderCircle,Plus,RefreshCw,Save,Search,ShieldCheck,Trash2} from 'lucide-vue-next';
import type {RepositoryPermissions} from '@oxen/shared';
import type {DatasetFieldConflictSummary,DatasetFieldsState} from '../../../../packages/shared/src/dataset-field-types';
import {resolveDatasetFieldMetadata} from '../../../../packages/shared/src/field-metadata';
import {globalFieldMetadata,type GlobalFieldCatalogState} from '../../../../packages/shared/src/global-fields';
import {createSampleFieldDraft,sampleFieldConfiguration,setSampleFieldControl,sampleFieldOptionColor,newSampleFieldOption,type SampleFieldControl,type SampleFieldDraft} from '../sample-field-config';
import {reorderSampleFieldDrafts,resetSampleFieldDraftOrder} from '../sample-field-order';
import {parseSampleFieldCheckpoint,restoreSampleFieldCheckpoint,sampleFieldCheckpointChanges,type SampleFieldFormCheckpoint} from '../sample-field-checkpoint';
import {createDatasetUiStateClient,type DatasetUiStateClient} from '../dataset-ui-state-client';
import {persistStableForm} from '../stable-form-checkpoint';
import {ApiError,queryString,request} from '../api';
import {useAppStore} from '../stores/app';

const props=defineProps<{base:string;branch:string}>(),emit=defineEmits<{saved:[];'configure-dataset':[]}>(),app=useAppStore();
const permissions=inject<ComputedRef<RepositoryPermissions>>('repositoryPermissions');
const router=useRouter();
const state=ref<DatasetFieldsState>(),drafts=ref<SampleFieldDraft[]>([]),selected=ref(''),search=ref(''),newId=ref(''),message=ref('更新样本字段配置');
const loading=ref(false),busy=ref(false),error=ref(''),localError=ref(''),saved=ref(false),notConfigured=ref(false),conflicts=ref<DatasetFieldConflictSummary>(),baseline=ref('');
const deleteTarget=ref(''),deleteConfirmation=ref('');
const deleteDialog=ref<HTMLElement>();let deleteOpener:HTMLElement|undefined;
const dragSource=ref(''),dragTarget=ref(''),dragPlacement=ref<'before'|'after'>('before'),orderNotice=ref('');
const checkpointError=ref(''),checkpointSaving=ref(false),checkpointPresent=ref(false),checkpointAt=ref(''),recoveryNotice=ref('');
const pendingRecovery=ref<SampleFieldFormCheckpoint>(),recoveryInvalid=ref(false),checkpointReadFailed=ref(false),persistenceReady=ref(false),lastStored=ref('');
const checkpointConflict=ref(false),concurrentPayload=ref<unknown>(),concurrentLoaded=ref(false),concurrentAt=ref('');
let generation=0,checkpointClient:DatasetUiStateClient|undefined,concurrentClient:DatasetUiStateClient|undefined,checkpointTimer:ReturnType<typeof setTimeout>|undefined;
const labels:Record<SampleFieldControl,string>={auto:'自动（沿用原值）',string:'文本 string',number:'数字 number',integer:'整数 integer',boolean:'布尔 boolean',array:'数组 array',object:'对象 object',enum:'单选 enum',multiselect:'多选 multiselect'};
const scalarLabels={auto:'不限制选项类型',string:'文本 string',number:'数字 number',integer:'整数 integer',boolean:'布尔 boolean'};
const editor=computed(()=>drafts.value.find(field=>field.id===selected.value)),statistics=computed(()=>state.value?.fields.find(field=>field.id===selected.value));
const dirty=computed(()=>!!baseline.value&&JSON.stringify(drafts.value)!==baseline.value),canEdit=computed(()=>state.value?.capabilities.edit===true),configuredCount=computed(()=>drafts.value.filter(field=>field.enabled).length);
const visible=computed(()=>drafts.value.filter(field=>(field.id+' '+field.displayName+' '+field.description).toLocaleLowerCase().includes(search.value.toLocaleLowerCase())));
const orderDirty=computed(()=>!!state.value&&(drafts.value.some(field=>field.order!==(Object.hasOwn(state.value!.configuration,field.id)?state.value!.configuration[field.id]?.order:undefined))||[...state.value.fields.map(field=>field.id).filter(id=>drafts.value.some(field=>field.id===id)),...drafts.value.filter(field=>!state.value!.fields.some(saved=>saved.id===field.id)).map(field=>field.id)].join('\0')!==drafts.value.map(field=>field.id).join('\0')));
const mayConfigureDataset=computed(()=>permissions?.value.capabilities?.['data.edit']===true&&permissions.value.capabilities?.['tasks.manage']===true);
const selectedProtected=computed(()=>state.value?.protectedFields.includes(selected.value)===true);
const selectedGlobal=computed(()=>state.value?.globalFields?.active.includes(selected.value)===true);
const canDeleteSelected=computed(()=>canEdit.value&&!selectedProtected.value&&(!statistics.value||state.value?.capabilities.delete===true));
const deleteStatistics=computed(()=>state.value?.fields.find(field=>field.id===deleteTarget.value));
const recoveryChanges=computed(()=>pendingRecovery.value&&state.value?sampleFieldCheckpointChanges(pendingRecovery.value,state.value):[]);
const formCheckpoint=computed<SampleFieldFormCheckpoint|undefined>(()=>state.value?{version:1,baseCommit:state.value.commitId,baseConfiguration:state.value.configuration,drafts:drafts.value,selected:selected.value,search:search.value,newId:newId.value,message:message.value}:undefined);
const formSignature=computed(()=>formCheckpoint.value?JSON.stringify(formCheckpoint.value):'');
const checkpointUnsaved=computed(()=>persistenceReady.value&&(canEdit.value||checkpointPresent.value)&&formSignature.value!==lastStored.value);
const formBlocked=computed(()=>!!pendingRecovery.value||recoveryInvalid.value||checkpointReadFailed.value);
const context=()=>props.base+':'+props.branch+':'+(app.status?.identity?.kind??'guest')+':'+(app.status?.identity?.id??'guest');
const conflictName=(code:string)=>({required:'缺少必需字段',null:'当前不允许 null',type:'字段类型不匹配',enum:'原值不在单选项中','item-type':'数组项类型不匹配','item-enum':'数组项不在多选项中'}[code]??code);
function fill(value:DatasetFieldsState){state.value=value;drafts.value=value.fields.map(field=>createSampleFieldDraft(field.id,Object.hasOwn(value.configuration,field.id)?value.configuration[field.id]:undefined));baseline.value=JSON.stringify(drafts.value);orderNotice.value='';if(!drafts.value.some(field=>field.id===selected.value))selected.value=drafts.value[0]?.id??'';}
function edited(){saved.value=false;localError.value='';conflicts.value=undefined;if(editor.value)editor.value.enabled=true;}
function restore(checkpoint:SampleFieldFormCheckpoint){if(!state.value)return;const result=restoreSampleFieldCheckpoint(checkpoint,state.value);drafts.value=result.drafts;baseline.value=JSON.stringify(result.baseline);selected.value=checkpoint.selected;search.value=checkpoint.search;newId.value=checkpoint.newId;message.value=checkpoint.message;pendingRecovery.value=undefined;recoveryInvalid.value=false;recoveryNotice.value=result.advanced?'已恢复配置输入。分支已有新提交，字段定义未改的内容沿用最新版本；保存时仍会校验。':'已恢复上次的配置输入，尚未提交字段配置。';persistenceReady.value=true;}
async function load(){
  endDrag();orderNotice.value='';deleteTarget.value='';deleteConfirmation.value='';

  const current=++generation;clearTimeout(checkpointTimer);loading.value=true;persistenceReady.value=false;error.value='';checkpointError.value='';checkpointReadFailed.value=false;checkpointConflict.value=false;concurrentLoaded.value=false;concurrentClient=undefined;localError.value='';saved.value=false;notConfigured.value=false;conflicts.value=undefined;pendingRecovery.value=undefined;recoveryInvalid.value=false;recoveryNotice.value='';state.value=undefined;drafts.value=[];baseline.value='';checkpointPresent.value=false;checkpointAt.value='';
  const client=createDatasetUiStateClient({base:props.base,ref:props.branch,kind:'field-settings',context});checkpointClient=client;
  try{
    const result=await request<DatasetFieldsState>(props.base+'/dataset/fields'+queryString({ref:props.branch}));if(current!==generation)return;fill(result);
    if(!app.status?.identity||app.status.identity.kind==='guest'){lastStored.value=formSignature.value;persistenceReady.value=true;return;}
    const checkpoint=await client.load();if(current!==generation)return;checkpointPresent.value=!!checkpoint;checkpointAt.value=checkpoint?.updatedAt??'';
    if(checkpoint){lastStored.value=JSON.stringify(checkpoint.payload);try{const payload=parseSampleFieldCheckpoint(checkpoint.payload);if(sampleFieldCheckpointChanges(payload,result).length){pendingRecovery.value=payload;recoveryNotice.value='字段配置已被其他提交修改。请先对照，再决定如何继续；旧表单不会自动覆盖最新配置。';}else restore(payload);}catch(cause){recoveryInvalid.value=true;checkpointError.value=(cause as Error).message;}}
    else{lastStored.value=formSignature.value;persistenceReady.value=true;}
  }catch(cause){if(current===generation){if(state.value){checkpointReadFailed.value=true;checkpointError.value='无法读取本机配置草稿：'+(cause as Error).message;lastStored.value='';}else{error.value=(cause as Error).message;notConfigured.value=cause instanceof ApiError&&cause.code==='DATASET_NOT_CONFIGURED';}}}finally{if(current===generation)loading.value=false;}
}
async function persistCheckpoint(){
  clearTimeout(checkpointTimer);if(!state.value||!checkpointClient)return true;if(checkpointReadFailed.value)return false;if(!canEdit.value&&!checkpointPresent.value&&!dirty.value)return true;
  if(pendingRecovery.value||recoveryInvalid.value)return true;
  const current=generation,client=checkpointClient,payload=formCheckpoint.value,signature=formSignature.value;
  if(signature===lastStored.value)return true;if(!payload)return true;
  checkpointSaving.value=true;checkpointError.value='';
  try{const result=await client.save(payload,state.value.commitId);if(current!==generation)return false;lastStored.value=signature;checkpointPresent.value=true;checkpointAt.value=result.updatedAt;checkpointConflict.value=false;persistenceReady.value=true;return true;}
  catch(cause){if(current===generation){checkpointConflict.value=cause instanceof ApiError&&cause.code==='UI_STATE_REVISION_CONFLICT';checkpointError.value='配置输入尚未保留：'+(cause as Error).message+'。当前输入仍在本页，请重试后再离开。';}return false;}
  finally{if(current===generation)checkpointSaving.value=false;}
}
async function mayLeave(){if(busy.value)return false;return persistStableForm({generation:()=>generation,signature:()=>formSignature.value,persist:persistCheckpoint,settle:nextTick});}
async function refresh(){if(await mayLeave())await load();}
async function continueRecovery(){if(!pendingRecovery.value)return;if(!await app.confirmAction('将保留你改动过的字段输入；未改动的字段沿用最新配置。若双方修改同一字段，你的输入会在之后明确保存时替换该字段。现在不会提交。',{title:'基于最新配置继续编辑',confirmLabel:'保留我的输入并继续'}))return;restore(pendingRecovery.value);await persistCheckpoint();}
async function discardCheckpoint(){if(!checkpointClient||busy.value)return;if(!await app.confirmAction('放弃本机保留的字段配置输入并读取已提交配置。已提交的数据和样本草稿均不受影响。',{title:'放弃配置输入',confirmLabel:'放弃配置输入'}))return;clearTimeout(checkpointTimer);persistenceReady.value=false;try{await checkpointClient.remove();checkpointPresent.value=false;checkpointError.value='';checkpointReadFailed.value=false;checkpointConflict.value=false;concurrentLoaded.value=false;pendingRecovery.value=undefined;recoveryInvalid.value=false;recoveryNotice.value='';if(state.value)fill(state.value);newId.value='';search.value='';message.value='更新样本字段配置';lastStored.value=formSignature.value;persistenceReady.value=true;}catch(cause){checkpointConflict.value=cause instanceof ApiError&&cause.code==='UI_STATE_REVISION_CONFLICT';checkpointError.value='未能删除配置草稿：'+(cause as Error).message;}}
async function goToData(){if(await mayLeave())await router.push({path:props.base+'/table',query:{branch:props.branch}});}
async function inspectConcurrent(){const current=generation,candidate=createDatasetUiStateClient({base:props.base,ref:props.branch,kind:'field-settings',context});checkpointSaving.value=true;try{const stored=await candidate.load();if(current!==generation)return;concurrentClient=candidate;concurrentPayload.value=stored?.payload;concurrentAt.value=stored?.updatedAt??'';concurrentLoaded.value=true;}catch(cause){if(current===generation)checkpointError.value='未能读取另一处保留输入：'+(cause as Error).message;}finally{if(current===generation)checkpointSaving.value=false;}}
async function keepCurrentInputs(){if(!concurrentClient||!concurrentLoaded.value)return;if(!await app.confirmAction('将用本页输入替换刚核对的其他会话配置草稿，仅修改本机保留输入，不提交字段。其他会话之后保存时会提示冲突。',{title:'保留本页配置输入',confirmLabel:'保留本页输入'}))return;checkpointClient=concurrentClient;lastStored.value=JSON.stringify(concurrentClient.state?.payload??null);checkpointConflict.value=false;concurrentLoaded.value=false;await persistCheckpoint();}
async function useConcurrentInputs(){if(!concurrentClient||!concurrentLoaded.value||concurrentPayload.value===undefined)return;let payload:SampleFieldFormCheckpoint;try{payload=parseSampleFieldCheckpoint(concurrentPayload.value);}catch(cause){checkpointError.value=(cause as Error).message;return;}if(!await app.confirmAction('将放弃本页尚未保留的配置输入，改为恢复刚核对的其他会话草稿。不会提交字段配置。',{title:'恢复其他会话的保留输入',confirmLabel:'恢复该保留输入'}))return;const current=generation;checkpointSaving.value=true;try{const fresh=await request<DatasetFieldsState>(props.base+'/dataset/fields'+queryString({ref:props.branch}));if(current!==generation)return;persistenceReady.value=false;fill(fresh);checkpointClient=concurrentClient;checkpointPresent.value=true;checkpointAt.value=concurrentClient.state?.updatedAt??'';checkpointConflict.value=false;concurrentLoaded.value=false;checkpointError.value='';lastStored.value=JSON.stringify(payload);if(sampleFieldCheckpointChanges(payload,fresh).length){pendingRecovery.value=payload;recoveryNotice.value='该草稿与最新字段定义不同，请对照后继续。';}else restore(payload);}catch(cause){if(current===generation)checkpointError.value=(cause as Error).message;}finally{if(current===generation)checkpointSaving.value=false;}}
function choose(id:string){selected.value=id;localError.value='';}
function applyFieldOrder(sourceId:string,targetId:string,placement:'before'|'after'){
  if(!canEdit.value||busy.value||formBlocked.value)return;
  try{const next=reorderSampleFieldDrafts(drafts.value,visible.value.map(field=>field.id),sourceId,targetId,placement);if(next.every((field,index)=>field===drafts.value[index]))return;drafts.value=next;saved.value=false;localError.value='';conflicts.value=undefined;orderNotice.value=`${sourceId} 已移到可见字段第${visible.value.findIndex(field=>field.id===sourceId)+1}位。顺序尚未提交，保存字段后应用到数据编辑。`;}
  catch(cause){localError.value=(cause as Error).message;}
}
function moveField(id:string,direction:-1|1){const index=visible.value.findIndex(field=>field.id===id),target=visible.value[index+direction];if(target)applyFieldOrder(id,target.id,direction<0?'before':'after');}
function startDrag(event:DragEvent,id:string){if(!canEdit.value||busy.value||formBlocked.value){event.preventDefault();return;}dragSource.value=id;if(event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',id);}}
function endDrag(){dragSource.value='';dragTarget.value='';}
function overDrag(event:DragEvent,id:string){if(!dragSource.value||dragSource.value===id||busy.value||formBlocked.value)return;event.preventDefault();dragTarget.value=id;const rect=(event.currentTarget as HTMLElement).getBoundingClientRect();dragPlacement.value=event.clientY<rect.top+rect.height/2?'before':'after';if(event.dataTransfer)event.dataTransfer.dropEffect='move';}
function dropField(event:DragEvent,id:string){if(!dragSource.value)return;event.preventDefault();event.stopPropagation();applyFieldOrder(dragSource.value,id,dragTarget.value===id?dragPlacement.value:'before');endDrag();}
function resetFieldOrder(){if(!state.value||!canEdit.value||busy.value||formBlocked.value)return;drafts.value=resetSampleFieldDraftOrder(drafts.value,state.value.fields.map(field=>field.id),state.value.configuration);saved.value=false;localError.value='';orderNotice.value='已还原已保存的字段顺序，其他字段输入保留。';}
function add(){if(!canEdit.value||busy.value)return;const id=newId.value.trim();if(!id||id.length>500){localError.value='请输入1至500个字符的字段 ID。';return;}if(drafts.value.some(field=>field.id===id)){localError.value='此字段 ID 已存在。';return;}const field=createSampleFieldDraft(id,{});drafts.value.push(field);selected.value=id;search.value='';newId.value='';edited();}
async function changeControl(value:SampleFieldControl,element:HTMLSelectElement){const field=editor.value;if(!field)return;const current=generation;if((field.options.length||field.control!=='auto')&&!await app.confirmAction('更换控件会替换此字段的类型和选项约束。源样本保持原值，保存时将校验已有数据。',{title:'更换字段类型',confirmLabel:'确认更换'})){element.value=field.control;return;}if(current!==generation||editor.value!==field)return;setSampleFieldControl(field,value);edited();}
function addOption(){const field=editor.value;if(!field)return;field.options.push(newSampleFieldOption(field));edited();}
function resetField(){const field=editor.value;if(!field||!state.value)return;const replacement=createSampleFieldDraft(field.id,Object.hasOwn(state.value.configuration,field.id)?state.value.configuration[field.id]:undefined);if(field.order!==undefined){replacement.order=field.order;replacement.enabled=true;}drafts.value[drafts.value.indexOf(field)]=replacement;saved.value=false;localError.value='';conflicts.value=undefined;}
async function removeConfiguration(){const field=editor.value;if(!field)return;if(!await app.confirmAction('移除此字段的自定义名称、帮助、类型约束和列宽，并将“是否导出”和“是否展示”恢复为默认勾选。当前排序及源字段和值仍保留；排序可用“还原已保存顺序”单独恢复。',{title:'移除字段配置',confirmLabel:'移除配置'}))return;const replacement=createSampleFieldDraft(field.id);if(field.order!==undefined){replacement.order=field.order;replacement.enabled=true;}if(!state.value?.fields.some(item=>item.id===field.id)){drafts.value=drafts.value.filter(item=>item!==field);selected.value=drafts.value[0]?.id??'';}else drafts.value[drafts.value.indexOf(field)]=replacement;saved.value=false;localError.value='';conflicts.value=undefined;}
async function synchronizeGlobalFields(){
  if(!canEdit.value||busy.value||formBlocked.value)return;const current=generation;if(!await mayLeave()||current!==generation)return;
  busy.value=true;error.value='';
  try{const {catalog}=await request<GlobalFieldCatalogState>('/global-fields/catalog');if(current!==generation)return;
    for(const [id,metadata] of Object.entries(globalFieldMetadata(catalog))){const previous=drafts.value.find(field=>field.id===id),field=createSampleFieldDraft(id,metadata);if(previous){for(const key of ['order','export','visible'] as const)(field as unknown as Record<string,unknown>)[key]=previous[key];drafts.value[drafts.value.indexOf(previous)]=field;}else drafts.value.push(field);}
    saved.value=false;conflicts.value=undefined;recoveryNotice.value=`已载入全局字段规范 r${catalog.revision}，样本值未改动。请校验并保存字段后应用到当前分支。`;await persistCheckpoint();
  }catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)busy.value=false;}
}
async function openDelete(){if(!editor.value||!canDeleteSelected.value||busy.value||formBlocked.value)return;deleteOpener=document.activeElement as HTMLElement;deleteTarget.value=editor.value.id;deleteConfirmation.value='';await nextTick();deleteDialog.value?.querySelector<HTMLInputElement>('input')?.focus();}
function closeDelete(){if(busy.value)return;deleteTarget.value='';deleteConfirmation.value='';if(deleteOpener?.isConnected)deleteOpener.focus();}
function deleteKeydown(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();closeDelete();return;}if(event.key!=='Tab')return;const targets=[...(deleteDialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled)')??[])];if(!targets.length)return;const first=targets[0]!,last=targets.at(-1)!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
async function deleteField(){
  const fieldId=deleteTarget.value;if(!fieldId||deleteConfirmation.value!==fieldId||!state.value||!canDeleteSelected.value||busy.value||formBlocked.value)return;
  if(!statistics.value){drafts.value=drafts.value.filter(field=>field.id!==fieldId);selected.value=drafts.value[0]?.id??'';deleteTarget.value='';saved.value=false;await persistCheckpoint();return;}
  const current=generation;if(!await mayLeave()||current!==generation||!state.value)return;
  const checkpoint=JSON.parse(JSON.stringify(formCheckpoint.value)) as SampleFieldFormCheckpoint,expectedCommit=state.value.commitId;
  busy.value=true;persistenceReady.value=false;error.value='';localError.value='';
  try{
    const result=await request<DatasetFieldsState>(props.base+'/dataset/fields/delete',{method:'POST',body:JSON.stringify({ref:props.branch,expectedCommit,fieldId,confirmFieldId:deleteConfirmation.value,message:`删除样本字段 ${fieldId}`})});
    if(current!==generation)return;
    checkpoint.drafts=checkpoint.drafts.filter(field=>field.id!==fieldId);delete checkpoint.baseConfiguration[fieldId];checkpoint.selected=checkpoint.drafts[0]?.id??'';
    fill(result);restore(checkpoint);deleteTarget.value='';deleteConfirmation.value='';conflicts.value=undefined;
    recoveryNotice.value='字段已从当前样本和配置中删除，并创建一次新提交。其他尚未保存的配置输入仍保留；历史版本和原始归档不变。';
    await persistCheckpoint();app.notify(`字段 ${fieldId} 已删除。`);emit('saved');
  }catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation){busy.value=false;persistenceReady.value=true;}}
}
async function save(){
  if(!state.value||!canEdit.value||!dirty.value||busy.value||pendingRecovery.value||recoveryInvalid.value)return;
  const current=generation;
  // Saving input may await the network; capture validated fields and message only after that input settles.
  if(!await mayLeave()||current!==generation||!state.value||!canEdit.value||!dirty.value||busy.value||formBlocked.value)return;
  let fields;try{fields=sampleFieldConfiguration(drafts.value);}catch(cause){localError.value=(cause as Error).message;return;}
  const commitMessage=message.value.trim(),expectedCommit=state.value.commitId;
  if(!commitMessage){localError.value='请填写提交说明。';return;}
  busy.value=true;persistenceReady.value=false;error.value='';localError.value='';conflicts.value=undefined;
  try{const result=await request<DatasetFieldsState>(props.base+'/dataset/fields',{method:'PUT',body:JSON.stringify({ref:props.branch,expectedCommit,fields,message:commitMessage})});if(current!==generation)return;fill(result);saved.value=true;recoveryNotice.value='';try{await checkpointClient?.remove();checkpointPresent.value=false;checkpointError.value='';lastStored.value=formSignature.value;}catch(cause){checkpointConflict.value=cause instanceof ApiError&&cause.code==='UI_STATE_REVISION_CONFLICT';checkpointError.value='字段已提交，但旧配置输入未清理：'+(cause as Error).message+'。未删除其他会话的新草稿。';}app.notify('样本字段配置已校验并保存。');emit('saved');}catch(cause){if(current!==generation)return;error.value=(cause as Error).message;if(cause instanceof ApiError&&cause.details&&typeof cause.details==='object'){const detail=cause.details as Partial<DatasetFieldConflictSummary>;if(typeof detail.conflictCount==='number'&&Array.isArray(detail.conflicts))conflicts.value=detail as DatasetFieldConflictSummary;}}finally{if(current===generation){busy.value=false;persistenceReady.value=true;}}
}
const unregister=app.registerDraftGuard(mayLeave);onBeforeRouteLeave(mayLeave);onBeforeRouteUpdate((to,from)=>to.fullPath===from.fullPath||mayLeave());
function unload(event:BeforeUnloadEvent){if(checkpointUnsaved.value||checkpointSaving.value||busy.value){event.preventDefault();event.returnValue='';}}window.addEventListener('beforeunload',unload);
watch([formSignature,persistenceReady,loading],()=>{clearTimeout(checkpointTimer);if(!loading.value&&!busy.value&&persistenceReady.value&&!pendingRecovery.value&&!recoveryInvalid.value&&!checkpointConflict.value&&(canEdit.value||checkpointPresent.value)&&formSignature.value!==lastStored.value)checkpointTimer=setTimeout(()=>{void persistCheckpoint();},300);});
watch([()=>props.base,()=>props.branch,()=>app.status?.identity?.id,()=>app.status?.identity?.kind],load,{immediate:true});
onBeforeUnmount(()=>{generation++;clearTimeout(checkpointTimer);unregister();window.removeEventListener('beforeunload',unload);});
</script>

<template>
<section class="sample-fields-panel panel" aria-label="样本字段配置"><header><Columns3 :size="21"/><div><h3>样本字段</h3><p>维护源字段的显示名称、类型及 Release 导出选项，供数据编辑和交付使用。</p></div><button class="btn btn-ghost" :disabled="loading||busy" @click="refresh"><RefreshCw :size="15"/>重新读取</button></header>
  <div v-if="loading" class="empty" role="status"><LoaderCircle class="spin" :size="23"/><p>正在核对当前分支的字段及实际类型…</p></div>
  <p v-if="error" class="error-state" role="alert">{{error}}<span v-if="dirty">当前配置修改仍保留。</span><button v-if="!dirty" class="btn btn-ghost" @click="load">重试</button></p>
  <div v-if="notConfigured" class="sample-fields-notice"><p>此分支尚未配置完整逻辑数据集入口。</p><button v-if="mayConfigureDataset" class="btn" @click="emit('configure-dataset')">前往数据集配置</button></div>
  <template v-if="state&&!loading"><div class="sample-fields-version"><GitBranch :size="14"/><span>{{branch}}</span><code>{{state.commitId.slice(0,12)}}</code><span>{{state.totalRows.toLocaleString()}}条样本 · {{configuredCount}}项自定义配置</span></div>
    <div class="sample-fields-checkpoint" aria-live="polite"><p>{{checkpointSaving?'正在保留本机配置输入…':checkpointUnsaved?'配置输入等待保留…':checkpointPresent?'配置输入已在本机保留，尚未提交。':'修改配置后自动保留在本机，离开无需先提交。'}}<small v-if="checkpointAt">{{new Date(checkpointAt).toLocaleString('zh-CN')}}</small></p><div><button class="btn btn-ghost" :disabled="busy||checkpointSaving" @click="goToData">保留配置并前往数据编辑</button><button v-if="checkpointPresent||dirty||formBlocked" class="btn btn-ghost" :disabled="busy||checkpointSaving" @click="discardCheckpoint">放弃配置输入</button></div></div>
    <p v-if="checkpointError" class="error-state" role="alert">{{checkpointError}}<button v-if="checkpointReadFailed" class="btn btn-ghost" @click="load">重试读取配置草稿</button><button v-else-if="checkpointConflict" class="btn btn-ghost" :disabled="checkpointSaving" @click="inspectConcurrent">核对其他会话的保留输入</button><button v-else-if="!formBlocked" class="btn btn-ghost" :disabled="checkpointSaving" @click="persistCheckpoint">重试保留输入</button></p>
    <section v-if="concurrentLoaded" class="sample-fields-recovery"><h4>其他会话已修改配置草稿</h4><p>本页输入尚未覆盖它。请核对后明确选择。{{concurrentAt?new Date(concurrentAt).toLocaleString('zh-CN'):''}}</p><details v-if="concurrentPayload!==undefined"><summary>查看其他会话的配置输入</summary><pre>{{JSON.stringify(concurrentPayload,null,2)}}</pre></details><p v-else>其他会话已清除保留输入。</p><button class="btn" :disabled="checkpointSaving" @click="keepCurrentInputs">保留本页输入</button><button v-if="concurrentPayload!==undefined" class="btn btn-ghost" :disabled="checkpointSaving" @click="useConcurrentInputs">恢复该保留输入</button></section>
    <p v-if="recoveryNotice" class="sample-fields-notice" role="status">{{recoveryNotice}}</p>
    <section v-if="pendingRecovery" class="sample-fields-recovery"><h4>最新字段配置与保留输入的基线不同</h4><p>以下仅展示字段定义，不包含样本正文。继续时只恢复你改动过的字段，未改动字段沿用最新配置。</p><details v-for="change in recoveryChanges" :key="change.id"><summary>{{change.id}}</summary><div><section><strong>保留输入的原定义</strong><pre>{{JSON.stringify(change.before??null,null,2)}}</pre></section><section><strong>最新已提交定义</strong><pre>{{JSON.stringify(change.current??null,null,2)}}</pre></section><section><strong>本机保留的表单输入</strong><pre>{{JSON.stringify(pendingRecovery.drafts.find(field=>field.id===change.id)??null,null,2)}}</pre></section></div></details><button class="btn" @click="continueRecovery">对照后继续我的修改</button></section>
    <p v-if="!canEdit" class="sample-fields-notice">当前身份只读查看。具备“采用规范”权限的负责人或指定人员可以维护样本字段。</p>
    <div class="sample-fields-notice">配置与当前分支保存。新增配置不会向样本填充默认值，更换类型也不会自动转换原值；已有数据不匹配时会阻止保存。</div>
    <section class="sample-fields-global"><p><strong>全局字段</strong> 活动目录字段的名称、含义与选项由管理员在“字段管理”统一维护；这里可调整展示、排序与导出，列宽在数据编辑表格拖动保存。同步不转换样本值，已退出全局的字段仍保留项目来源快照，可由项目管理员明确删除。</p><button v-if="canEdit" class="btn" :disabled="busy||formBlocked" @click="synchronizeGlobalFields">同步全局字段</button></section>
    <form v-if="canEdit" class="sample-field-add" @submit.prevent="add"><label for="new-sample-field">新增字段 ID</label><input id="new-sample-field" v-model="newId" :disabled="busy||formBlocked" maxlength="500" placeholder="例如 review_note"/><button class="btn" :disabled="busy||formBlocked||!newId.trim()"><Plus :size="14"/>加入配置</button></form>
    <div class="sample-fields-layout"><aside><label class="sample-field-search"><Search :size="14"/><input v-model="search" aria-label="搜索样本字段" placeholder="搜索 ID、显示名或帮助…"/></label>
      <div v-if="canEdit" class="sample-field-order-help"><p>拖动左侧手柄排序，也可用上下按钮或Alt+方向键。搜索时仅调整可见字段，隐藏字段保留。</p><button v-if="orderDirty" class="btn btn-ghost" :disabled="busy||formBlocked" @click="resetFieldOrder">还原已保存顺序</button></div>
      <div class="sample-field-list" role="list" aria-label="样本字段顺序"><div v-for="(field,index) in visible" :key="field.id" class="sample-field-item" :class="{active:selected===field.id,'read-only':!canEdit,dragging:dragSource===field.id,'drop-before':dragTarget===field.id&&dragPlacement==='before','drop-after':dragTarget===field.id&&dragPlacement==='after'}" role="listitem" @dragover="overDrag($event,field.id)" @drop="dropField($event,field.id)" @keydown.alt.up.prevent="moveField(field.id,-1)" @keydown.alt.down.prevent="moveField(field.id,1)">
        <button v-if="canEdit" class="sample-field-drag" :draggable="!busy&&!formBlocked" :disabled="busy||formBlocked" :aria-label="`拖动排序字段 ${field.id}`" title="拖动排序；Alt+上/下移动" @dragstart="startDrag($event,field.id)" @dragend="endDrag"><GripVertical :size="14"/></button>
        <button class="sample-field-choice" :aria-current="selected===field.id?'true':undefined" @click="choose(field.id)"><code>{{field.id}}</code><span>{{field.displayName||resolveDatasetFieldMetadata(field.id).displayName||'未设置显示名称'}}</span><small>{{field.enabled?'已配置':'自动推断'}}</small></button>
        <div v-if="canEdit" class="sample-field-move"><button :disabled="busy||formBlocked||index===0" :aria-label="`上移字段 ${field.id}`" title="上移" @click="moveField(field.id,-1)"><ArrowUp :size="12"/></button><button :disabled="busy||formBlocked||index===visible.length-1" :aria-label="`下移字段 ${field.id}`" title="下移" @click="moveField(field.id,1)"><ArrowDown :size="12"/></button></div>
      </div><p v-if="!visible.length">没有匹配字段。</p></div></aside>
      <article v-if="editor" class="sample-field-editor"><header><div><h4>{{editor.id}}</h4><span v-if="selectedProtected" class="badge"><ShieldCheck :size="12"/>活动全局、身份或源值受保护</span><span v-if="editor.original?.globalField" class="badge">全局来源 r{{editor.original.globalField.revision}}{{state?.globalFields?.retired.includes(editor.id)?' · 已退出全局，项目保留':''}}</span></div><small v-if="statistics">存在 {{statistics.present}} · 缺失 {{statistics.missing}} · null {{statistics.nulls}}<br/>实际类型 {{statistics.inferredType}}</small><small v-else>新逻辑字段 · 目前没有源值</small></header>
        <fieldset :disabled="!canEdit||busy||formBlocked"><div class="sample-field-grid"><label>字段 ID<input :value="editor.id" readonly class="mono"/></label><label>显示名称<input v-model="editor.displayName" :disabled="selectedGlobal" maxlength="120" :placeholder="resolveDatasetFieldMetadata(editor.id).displayName||'未提供别名'" @input="editor.displayNameSet=true;edited()"/></label></div>
          <label class="sample-field-export"><input type="checkbox" :checked="editor.export!==false" aria-label="是否导出" @change="editor.export=($event.target as HTMLInputElement).checked;edited()"/>是否导出（Release）</label><p class="sample-field-help">默认勾选。取消后，正式 Release 的样本记录不包含此整个字段；不会删除源值或隐藏编辑列。工作快照仍保留完整数据。导出选项不是访问权限。</p>
          <label class="sample-field-export"><input type="checkbox" :checked="editor.visible!==false" aria-label="是否展示" @change="editor.visible=($event.target as HTMLInputElement).checked;edited()"/>是否展示（数据编辑表格）</label><p class="sample-field-help">默认勾选。取消并保存后，此源字段不再出现在数据编辑表格；样本详情、搜索和导出仍保留，是否导出由上方选项单独决定。展示选项不是访问权限。</p>
          <label>帮助说明<textarea v-model="editor.description" :disabled="selectedGlobal" rows="3" maxlength="4000" :placeholder="resolveDatasetFieldMetadata(editor.id).description||'说明字段含义、边界和使用方法…'" @input="editor.descriptionSet=true;edited()"/></label>
          <label>字段类型 / 编辑控件<select :value="editor.control" :disabled="selectedGlobal" aria-label="样本字段类型" @change="changeControl(($event.target as HTMLSelectElement).value as SampleFieldControl,$event.target as HTMLSelectElement)"><option v-for="(label,id) in labels" :key="id" :value="id">{{label}}</option></select></label>
          <label v-if="['enum','multiselect','array'].includes(editor.control)">{{editor.control==='array'?'数组项类型':'选项类型'}}<select v-model="editor.optionType" :disabled="selectedGlobal" aria-label="选项原值类型" @change="edited"><option v-for="(label,id) in scalarLabels" :key="id" :value="id">{{label}}</option></select></label>
          <div class="sample-field-flags"><label><input v-model="editor.nullable" :disabled="selectedGlobal" type="checkbox" @change="editor.nullableSet=true;edited()"/>允许 null</label><label><input v-model="editor.required" :disabled="selectedGlobal" type="checkbox" @change="editor.requiredSet=true;edited()"/>每条样本必须含此字段</label></div><p class="sample-field-help">null与字段缺失分别控制。空字符串属于已有文本值，不等于null。</p>
          <fieldset :disabled="selectedGlobal"><section v-if="['enum','multiselect'].includes(editor.control)" class="sample-field-options"><header><strong>{{editor.control==='multiselect'?'多选原值':'单选原值'}}</strong><button type="button" class="btn btn-ghost" @click="addOption"><Plus :size="13"/>加入选项</button></header><p>每项按原始JSON类型保存，取值需要与现有样本一致。新选项自动分配不同颜色；可自行调整，颜色只影响展示。</p><div v-for="(option,index) in editor.options" :key="index" class="sample-field-option"><select v-model="option.type" :aria-label="`第${index+1}个选项的类型`" @change="edited"><option value="string">文本</option><option value="number">数字</option><option value="boolean">布尔</option></select><select v-if="option.type==='boolean'" v-model="option.text" :aria-label="`第${index+1}个选项的原值`" @change="edited"><option value="true">true</option><option value="false">false</option></select><input v-else v-model="option.text" :aria-label="`第${index+1}个选项的原值`" :placeholder="option.type==='number'?'原始数字值':'原始文本值'" @input="edited"/><label class="sample-field-option-color"><span>颜色</span><input type="color" :value="sampleFieldOptionColor(editor,index)" :aria-label="`第${index+1}个选项的颜色`" @input="option.color=($event.target as HTMLInputElement).value;edited()"/><code>{{sampleFieldOptionColor(editor,index)}}</code></label><button type="button" class="icon-button" :aria-label="`移除第${index+1}个选项`" @click="editor.options.splice(index,1);edited()"><Trash2 :size="14"/></button></div><p v-if="!editor.options.length">请加入至少一个选项。</p></section></fieldset>
        </fieldset><p v-if="selectedProtected" class="sample-field-help">全局预置、身份、来源、附件引用及既有真值字段受保护，不能在项目中删除。</p><footer v-if="canEdit"><button class="btn btn-ghost" :disabled="busy||formBlocked" @click="resetField">还原本字段</button><button v-if="editor.enabled&&!selectedGlobal&&!editor.original?.globalField&&!state?.globalFields?.retired.includes(editor.id)" class="btn btn-ghost" :disabled="busy||formBlocked" @click="removeConfiguration">移除自定义配置</button><button class="btn btn-ghost sample-field-delete" :disabled="busy||formBlocked||!canDeleteSelected" @click="openDelete"><Trash2 :size="13"/>删除字段</button></footer>
      </article><div v-else class="empty"><Columns3 :size="27"/><p>选择字段查看或维护配置。</p></div>
    </div>
    <p v-if="orderNotice" class="sample-field-order-notice" role="status">{{orderNotice}}</p>
    <p v-if="localError" class="error-state" role="alert">{{localError}}</p>
    <section v-if="conflicts" class="sample-field-conflicts"><h4>已有数据与配置不匹配</h4><p>{{conflicts.conflictCount}}处冲突，涉及{{conflicts.affectedRows}}条样本。{{conflicts.truncated?'下表只展示部分条目。':''}}源记录没有被转换或覆盖。</p><div><table><thead><tr><th>字段 ID</th><th>条目 ID</th><th>原因</th></tr></thead><tbody><tr v-for="(conflict,index) in conflicts.conflicts" :key="index"><td><code>{{conflict.field}}</code></td><td><code>{{conflict.rowId}}</code></td><td>{{conflictName(conflict.code)}}</td></tr></tbody></table></div></section>
    <footer class="sample-fields-save"><span v-if="saved" role="status"><CheckCircle2 :size="15"/>已校验并保存</span><span v-else>{{dirty?'有尚未保存的字段修改':'字段配置与当前版本一致'}}</span><label v-if="canEdit">提交说明<input v-model="message" :disabled="busy||formBlocked" maxlength="4000" placeholder="说明这次字段配置变更"/></label><button v-if="canEdit" class="btn btn-primary" :disabled="busy||formBlocked||!dirty||!message.trim()" @click="save"><LoaderCircle v-if="busy" class="spin" :size="15"/><Save v-else :size="15"/>{{busy?'正在校验与保存…':'校验并保存字段'}}</button></footer>
  </template>
  <div v-if="deleteTarget" class="modal-backdrop" @click.self="closeDelete" @keydown="deleteKeydown"><section ref="deleteDialog" class="modal sample-field-delete-dialog" role="dialog" aria-modal="true" aria-labelledby="delete-field-title"><h3 id="delete-field-title">删除样本字段</h3><p>将从当前分支的 <strong>{{deleteStatistics?.present??0}}</strong> 条样本中移除 <code>{{deleteTarget}}</code> 字段和值，并删除它的配置。{{deleteStatistics?'确认后创建一次新提交，其他未保存的配置继续保留。':'这是尚未保存的新字段，只移除当前配置输入。'}}历史版本及原始归档仍保留。</p><label>输入字段 ID 确认<input v-model="deleteConfirmation" aria-label="确认删除的字段 ID" :placeholder="deleteTarget" :disabled="busy" autocomplete="off"/></label><p v-if="error" class="error-state" role="alert">{{error}}</p><footer><button class="btn" :disabled="busy" @click="closeDelete">取消</button><button class="btn btn-danger" :disabled="busy||deleteConfirmation!==deleteTarget" @click="deleteField"><LoaderCircle v-if="busy" class="spin" :size="14"/>{{busy?'正在删除…':'确认删除字段'}}</button></footer></section></div>
</section>
</template>

<style scoped src="./SampleFieldsPanel.css"/>
